def adim(baslik):
    print("\n" + "=" * 70 + f"\n▶ {baslik}\n" + "=" * 70, flush=True)

def calistir(komut, env=None, izin_hata=False, sessiz=False, sure=1800):
    try:
        sonuc = subprocess.run(komut, shell=isinstance(komut, str), env=env,
                               stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                               text=True, timeout=sure)
    except subprocess.TimeoutExpired:
        raise RuntimeError(f"Komut {sure} saniyede bitmedi:\n{komut}")
    if not sessiz and sonuc.stdout.strip():
        print(sonuc.stdout[-3000:])
    if sonuc.returncode != 0 and not izin_hata:
        raise RuntimeError(f"Komut başarısız oldu:\n{komut}\n\n{sonuc.stdout[-3000:]}")
    return sonuc

