# --------------------------------------------------------------------------
baslangic = time.time()
os.makedirs(IS_DIZINI, exist_ok=True)
os.chdir(IS_DIZINI)

adim("1/5 Program kaynak kodu hazırlanıyor")
with open("app.py", "wb") as f:
    f.write(base64.b64decode("".join(PROGRAM_B64)))
compile(open("app.py", encoding="utf-8").read(), "app.py", "exec")
print(f"Kaynak kod hazır ve hatasız — {os.path.getsize('app.py'):,} bayt")

adim("2/5 Wine kuruluyor (Windows programlarını Linux'ta çalıştırma katmanı)")
ortam_apt = dict(os.environ, DEBIAN_FRONTEND="noninteractive")
calistir("dpkg --add-architecture i386", env=ortam_apt, sessiz=True, sure=300)
calistir("apt-get update -qq", env=ortam_apt, sessiz=True, sure=600)
calistir("apt-get install -y -qq --no-install-recommends wine wine64 wine32 xvfb cabextract",
         env=ortam_apt, izin_hata=True, sessiz=True, sure=900)
wine = shutil.which("wine") or shutil.which("wine64") or \
       next((p for p in ["/usr/lib/wine/wine64", "/usr/bin/wine64"] if os.path.exists(p)), None)
if not wine:
    calistir("apt-get install -y -qq wine64", env=ortam_apt, sessiz=True, sure=900)
    wine = shutil.which("wine64") or "/usr/lib/wine/wine64"
print("Wine:", calistir([wine, "--version"], sessiz=True, sure=120).stdout.strip())

# WINEDLLOVERRIDES: Mono/Gecko kurulum pencerelerini kapatir, yoksa Wine donar
W = dict(os.environ, WINEPREFIX="/root/.wine_ihale", WINEARCH="win64",
         WINEDEBUG="-all", DISPLAY=":99", WINEDLLOVERRIDES="mscoree,mshtml=")
subprocess.Popen(["Xvfb", ":99", "-screen", "0", "1024x768x16"],
                 stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
time.sleep(2)
calistir([wine, "wineboot", "-u"], env=W, izin_hata=True, sessiz=True, sure=600)
calistir("wineserver -w", env=W, izin_hata=True, sessiz=True, sure=300)
print("Wine ortamı hazır.")

adim(f"3/5 Windows için Python {PY_SURUM} kuruluyor")
PY_WIN = "C:\\Python310\\python.exe"
for parca in ["core", "exe", "lib", "tcltk"]:
    msi = f"{parca}.msi"
    calistir(f"wget -q https://www.python.org/ftp/python/{PY_SURUM}/amd64/{msi} -O {msi}",
             sure=300)
    calistir([wine, "msiexec", "/i", msi, "/qn", "TARGETDIR=C:\\Python310"],
             env=W, izin_hata=True, sessiz=True, sure=600)
    calistir("wineserver -w", env=W, izin_hata=True, sessiz=True, sure=300)
    print(f"  ✔ {parca}")
print(calistir([wine, PY_WIN, "--version"], env=W, sure=300).stdout.strip())

adim("4/5 Kütüphaneler kuruluyor (openpyxl, xlrd, PyInstaller)")
calistir([wine, PY_WIN, "-m", "ensurepip", "--upgrade"], env=W, izin_hata=True,
         sessiz=True, sure=600)
calistir("wineserver -w", env=W, izin_hata=True, sessiz=True, sure=300)
for paket in ["pip", "openpyxl", "xlrd", "pyinstaller"]:
    print(f"  → {paket} kuruluyor…", flush=True)
    t = time.time()
    calistir([wine, PY_WIN, "-m", "pip", "install", "--upgrade",
              "--only-binary=:all:", "--no-cache-dir",
              "--disable-pip-version-check", paket],
             env=W, izin_hata=True, sessiz=True, sure=900)
    calistir("wineserver -w", env=W, izin_hata=True, sessiz=True, sure=300)
    print(f"     ✔ {time.time()-t:.0f} sn")
print(calistir([wine, PY_WIN, "-c",
    "import tkinter, openpyxl, xlrd, PyInstaller;"
    "print('tkinter OK | openpyxl', openpyxl.__version__,"
    "'| xlrd', xlrd.__version__, '| PyInstaller', PyInstaller.__version__)"],
    env=W, sure=600).stdout.strip())

adim("5/5 EXE derleniyor")
shutil.rmtree("build", ignore_errors=True); shutil.rmtree("dist", ignore_errors=True)
calistir([wine, PY_WIN, "-m", "PyInstaller", "--onefile", "--windowed", "--clean",
          "--noconfirm", "--name", "IhaleAnaliz",
          "--collect-submodules", "openpyxl",
          "--hidden-import", "openpyxl.cell._writer",
          "--exclude-module", "pandas", "--exclude-module", "numpy",
          "--exclude-module", "matplotlib", "--exclude-module", "scipy",
          "--exclude-module", "PIL", "--exclude-module", "PyQt5",
          "app.py"], env=W, sessiz=True, sure=1800)
uretilen = glob.glob("dist/IhaleAnaliz.exe")
if not uretilen:
    raise RuntimeError("EXE oluşmadı. Yukarıdaki çıktıyı Claude ile paylaşın.")
shutil.copy(uretilen[0], EXE_ADI)
boyut = os.path.getsize(EXE_ADI) / 1e6
print(f"\n✔ {EXE_ADI}  ({boyut:.1f} MB)  —  toplam süre {(time.time()-baslangic)/60:.1f} dk")

from google.colab import files
files.download(os.path.join(IS_DIZINI, EXE_ADI))
print("İndirme başlatıldı. Tarayıcı izin isterse 'İzin ver' deyin.")
